function countPaths(rows, cols, memo = new Map()) {
  if (rows === 1 || cols === 1) return 1
  const key = rows + ',' + cols
  if (!memo.has(key)) {
    memo.set(key, countPaths(rows - 1, cols, memo) + countPaths(rows, cols - 1, memo))
  }
  return memo.get(key)
}

solution.typescript:
function countPaths(rows: number, cols: number, memo = new Map<string, number>()): number {
  if (rows === 1 || cols === 1) return 1
  const key = rows + ',' + cols
  const known = memo.get(key)
  if (known !== undefined) return known
  const total = countPaths(rows - 1, cols, memo) + countPaths(rows, cols - 1, memo)
  memo.set(key, total)
  return total
}

solution.python:
from functools import lru_cache

@lru_cache(maxsize=None)
def count_paths(rows, cols):
    if rows == 1 or cols == 1:
        return 1
    return count_paths(rows - 1, cols) + count_paths(rows, cols - 1)
